import json,pathlib
root=pathlib.Path('.')
names=['last_deployed_sha','last_deploy_status','deploy_stage','live_smoke_status','live_smoke_sha','live_smoke_checked_at','last_backup','selftest_ok','telegram_watchdog_status']
out={}
for n in names:
 p=root/'nas_state'/n
 out[n]=p.read_text(encoding='utf-8',errors='replace').strip() if p.is_file() else None
for n in ['production_baseline.json','telegram-watchdog-status.json']:
 p=root/'nas_state'/n
 try: out[n]=json.loads(p.read_text(encoding='utf-8',errors='replace')) if p.is_file() else None
 except Exception as e: out[n]={'parse_error':str(e)}
print(json.dumps(out,ensure_ascii=False))
